 "content": "def transform(grid):
    # Recolor the long separator lines and their crossing spine; leave isolated marks untouched.
    h, w = len(grid), len(grid[0])
    scaffold = set()
    for r, row in enumerate(grid):
        if all(v == row[0] for v in row):
            scaffold.update((r, c) for c in range(w))
    for c in range(w):
        if all(grid[r][c] == grid[0][c] for r in range(h)):
            scaffold.update((r, c) for r in range(h))
    # The scaffold is the color occurring on complete rows/columns, replaced by 2.
    out = [row[:] for row in grid]
    for r, c in scaffold:
        out[r][c] = 2
    return out
